using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;
using Microsoft.Extensions.Logging;

namespace McpStdioServer.Tools;

[McpServerToolType]
public sealed class ExternalApiTool
{
    [McpServerTool("fetch_data"), Description("Fetches data from an external API by resource path.")]
    public static async Task<string> FetchDataAsync(
        IHttpClientFactory httpClientFactory,
        ILogger<ExternalApiTool> logger,
        [Description("The API resource path to fetch (e.g. \"users/1\").")] string path,
        CancellationToken cancellationToken = default)
    {
        using var client = httpClientFactory.CreateClient("ExternalApi");

        logger.LogInformation("Fetching external API resource: {Path}", path);

        var response = await client.GetAsync(path, cancellationToken);

        if (!response.IsSuccessStatusCode)
        {
            var status = (int)response.StatusCode;
            logger.LogWarning("API returned {StatusCode} for {Path}", status, path);
            return $"Error: API returned status code {status}.";
        }

        var json = await response.Content.ReadAsStringAsync(cancellationToken);

        // Re-serialize to guarantee well-formed, indented JSON for the LLM.
        using var doc = JsonDocument.Parse(json);
        return JsonSerializer.Serialize(doc, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpStdioServer.Prompts;

[McpServerPromptType]
public sealed class SummarizationPrompt
{
    [McpServerPrompt("summarize"), Description("Summarize the provided text at a chosen detail level.")]
    public static IList<McpServerPromptMessage> Summarize(
        [Description("The text to summarize.")] string text,
        [Description("Detail level: brief, standard, or detailed. Defaults to standard.")] string style = "standard")
    {
        return
        [
            new McpServerPromptMessage(
                McpServerPromptMessageRole.User,
                new McpServerPromptContentPart
                {
                    Text = $"""
                        Summarize the following text.
                        Style: {style}

                        ---
                        {text}
                        ---
                        """
                })
        ];
    }
}

